parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "categoria": {
      "type": "string",
      "enum": ["CITA", "CONSULTA", "QUEJA", "URGENTE", "NO_RELACIONADO", "PERSONA"],
      "description": "Clasificación principal del mensaje entrante según la intención dominante del cliente."
    },
    "idioma": {
      "type": "string",
      "enum": ["es", "en"],
      "description": "Idioma en que escribe el cliente según la conversación: es (español) o en (inglés). Cualquier otro idioma cuenta como en."
    },
    "respuesta_cliente": {
      "type": "string",
      "minLength": 10,
      "maxLength": 500,
      "description": "Respuesta lista para enviarse tal cual al cliente, en su idioma. Debe tener contenido real y natural, nunca vacía ni genérica."
    },
    "pregunta_para_negocio": {
      "type": "string",
      "description": "Pregunta del cliente sobre el negocio cuya respuesta no aparece en la información del negocio, breve y en español, para avisarle al dueño. Cadena vacía si se pudo contestar, si no hay pregunta, o si es sobre disponibilidad para una cita."
    }
  },
  "required": ["categoria", "idioma", "respuesta_cliente", "pregunta_para_negocio"],
  "additionalProperties": false
}

parameters.jsCode:
// Solo el último mensaje de una ráfaga responde; los anteriores se retiran.
// Responde el último que se GUARDÓ (id más alto), pero los mensajes se juntan en el orden
// en que LLEGARON: una nota de voz tarda unos segundos en transcribirse y puede guardarse
// después de un texto que el cliente mandó más tarde.
const miId = $('Guardar Mensaje Pendiente').first().json.id;
const filas = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id != null)
  .sort((a, b) => a.id - b.id);
const ultimo = filas.length ? filas[filas.length - 1].id : null;
const esElUltimo = ultimo === miId;
const enOrden = [...filas].sort((a, b) =>
  String(a.recibido || '').localeCompare(String(b.recibido || '')) || a.id - b.id);

return [{
  json: {
    es_el_ultimo: esElUltimo,
    mensaje: esElUltimo ? enOrden.map(r => r.mensaje).join('\n') : '',
    hasta_id: esElUltimo ? ultimo : null,
    cantidad: filas.length,
  },
  pairedItem: { item: 0 },
}];

// Junta los datos del negocio y su catálogo en un solo objeto, y revisa que no falte nada.
const n = $('Cargar Negocio').first().json || {};
const servicios = $input.all()
  .map(i => i.json)
  .filter(s => s && s.nombre_es && s.activo !== false);

const faltan = [];
if (!n.cliente_id) {
  faltan.push('la fila del negocio en la tabla Negocios');
} else {
  for (const campo of ['nombre', 'tipo_negocio', 'telefono_whatsapp', 'correo_avisos', 'zona_horaria', 'horario_texto_es', 'horario_texto_en']) {
    if (!n[campo]) faltan.push(campo);
  }
}
if (!servicios.length) faltan.push('al menos un servicio activo en la tabla Servicios');
if (faltan.length) {
  throw new Error('Configuración incompleta del negocio: falta ' + faltan.join(', ') + '. Revisa las tablas Negocios y Servicios.');
}

const catalogo = servicios
  .map(s => {
    const nombre = s.nombre_en && s.nombre_en !== s.nombre_es ? `${s.nombre_es} / ${s.nombre_en}` : s.nombre_es;
    return `${nombre} ($${s.precio})`;
  })
  .join(', ');

return [{
  json: {
    ...n,
    horas_pausa: Number(n.horas_pausa) || 4,
    palabra_reactivar: n.palabra_reactivar || '🤖',
    servicios,
    catalogo_texto: catalogo,
  },
  pairedItem: { item: 0 },
}];

// Groq reconoce el formato por la extensión del archivo, y WhatsApp o Messenger no siempre la traen.
// Si la descarga falló, sigue sin audio: la transcripción también fallará y el cliente
// recibirá "No alcancé a escuchar bien tu nota de voz".
const item = $input.first();
const bin = item.binary && item.binary.data;
if (!bin) return [{ json: { sin_audio: true }, pairedItem: { item: 0 } }];

const mime = String(bin.mimeType || '').toLowerCase();
let ext = bin.fileExtension || 'ogg';
if (mime.includes('ogg') || mime.includes('opus')) ext = 'ogg';
else if (mime.includes('mpeg') || mime.includes('mp3')) ext = 'mp3';
else if (mime.includes('mp4')) ext = 'mp4';
else if (mime.includes('aac') || mime.includes('m4a')) ext = 'm4a';
else if (mime.includes('wav')) ext = 'wav';
else if (mime.includes('webm')) ext = 'webm';

bin.fileName = 'nota-de-voz.' + ext;
bin.fileExtension = ext;
return [{ json: { formato: ext }, binary: { data: bin }, pairedItem: { item: 0 } }];
